package org.eclipse.rdf4j.sail;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.query.Query;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.sail.helpers.SailConnectionWrapper;
import org.junit.jupiter.api.Test;

class SailConnectionParseOptionsCompatibilityTest {
	private static final QueryLanguage LANGUAGE = QueryLanguage.SPARQL;
	private static final Query.QueryType TYPE = Query.QueryType.TUPLE;
	private static final String QUERY = "SELECT * WHERE {}";
	private static final Optional<TupleExpr> LEGACY_RESULT = Optional.of(new SingletonSet());

	@Test
	void legacySailDefaultFallsBackOnlyForDefaultPolicy() {
		AtomicInteger legacyCalls = new AtomicInteger();
		SailConnection connection = legacyConnection(legacyCalls);

		Optional<TupleExpr> defaultResult = connection.prepareQuery(LANGUAGE, TYPE, QUERY, null,
				QueryParseOptions.DEFAULT);
		assertSame(LEGACY_RESULT.get(), defaultResult.orElseThrow());
		assertEquals(1, legacyCalls.get());

		assertFalse(connection.prepareQuery(LANGUAGE, TYPE, QUERY, null, QueryParseOptions.STRICT).isPresent());
		assertEquals(1, legacyCalls.get(), "strict syntax policy must decline without invoking the legacy parser");
		assertThrows(NullPointerException.class,
				() -> connection.prepareQuery(LANGUAGE, TYPE, QUERY, null, null));
		assertEquals(1, legacyCalls.get());
	}

	@Test
	void sailConnectionWrapperForwardsTheConfiguredPolicy() {
		List<QueryParseOptions> forwarded = new ArrayList<>();
		SailConnection delegate = (SailConnection) Proxy.newProxyInstance(SailConnection.class.getClassLoader(),
				new Class<?>[] { SailConnection.class }, (proxy, method, args) -> {
					if (method.getName().equals("prepareQuery") && method.getParameterCount() == 5) {
						forwarded.add((QueryParseOptions) args[4]);
						return LEGACY_RESULT;
					}
					throw new AssertionError("Unexpected delegate call: " + method);
				});
		SailConnection wrapper = new SailConnectionWrapper(delegate);

		assertSame(LEGACY_RESULT.get(), wrapper.prepareQuery(LANGUAGE, TYPE, QUERY, null, QueryParseOptions.STRICT)
				.orElseThrow());
		assertSame(LEGACY_RESULT.get(), wrapper.prepareQuery(LANGUAGE, TYPE, QUERY, null, QueryParseOptions.DEFAULT)
				.orElseThrow());
		assertEquals(List.of(QueryParseOptions.STRICT, QueryParseOptions.DEFAULT), forwarded);
	}

	@Test
	void sailConnectionWrapperDispatchesDefaultPolicyThroughLegacySubclassOverrides() {
		AtomicInteger legacyCalls = new AtomicInteger();
		SailConnection delegate = legacyConnection(new AtomicInteger());

		class LegacyWrapper extends SailConnectionWrapper {
			LegacyWrapper(SailConnection wrapped) {
				super(wrapped);
			}

			@Override
			public Optional<TupleExpr> prepareQuery(QueryLanguage ql, Query.QueryType type, String query,
					String baseURI) {
				legacyCalls.incrementAndGet();
				return super.prepareQuery(ql, type, query, baseURI);
			}
		}

		SailConnection nested = new SailConnectionWrapper(new LegacyWrapper(delegate));
		assertSame(LEGACY_RESULT.get(), nested.prepareQuery(LANGUAGE, TYPE, QUERY, null, QueryParseOptions.DEFAULT)
				.orElseThrow());
		assertEquals(1, legacyCalls.get(), "default policy must dispatch through the legacy wrapper override");
		assertSame(LEGACY_RESULT.get(), nested.prepareQuery(LANGUAGE, TYPE, QUERY, null).orElseThrow());
		assertEquals(2, legacyCalls.get(), "direct legacy calls must reach the override without recursing");

		assertFalse(nested.prepareQuery(LANGUAGE, TYPE, QUERY, null, QueryParseOptions.STRICT).isPresent());
		assertEquals(2, legacyCalls.get(), "strict policy must not invoke a legacy-only override");
	}

	private static SailConnection legacyConnection(AtomicInteger legacyCalls) {
		InvocationHandler handler = (proxy, method, args) -> {
			if (method.getName().equals("prepareQuery") && method.getParameterCount() == 4) {
				legacyCalls.incrementAndGet();
				return LEGACY_RESULT;
			}
			if (method.isDefault()) {
				return InvocationHandler.invokeDefault(proxy, method, args);
			}
			throw new AssertionError("Unexpected legacy Sail method: " + method);
		};
		return (SailConnection) Proxy.newProxyInstance(SailConnection.class.getClassLoader(),
				new Class<?>[] { SailConnection.class }, handler);
	}
}
